<?php require'inc.php';head('Dish');$p=row("SELECT p.*,c.name cat FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?",'i',(int)($_GET['id']??0));
if(!$p)echo"Not found";else{echo"<div class=card>".img($p['image'])."<h2>".e($p['name'])."</h2><p>Category: ".e($p['cat'])."</p><p>".e($p['description'])."</p><h3>₹".number_format(price($p))." <span class=old>₹".number_format($p['price'])."</span> (".(float)$p['discount']."% off)</h3><p>".($p['stock']>0?"In stock: {$p['stock']}":"Out of stock")."</p>";
if($p['stock']>0)echo"<form method=post action=cart.php><input type=hidden name=add value={$p['id']}>Quantity<input type=number name=qty value=1 min=1 max={$p['stock']}><button>Add to Cart</button> <button name=buy value=1>Buy Now</button></form>";echo"</div>";}foot();
